class AnimationDemoScreen extends StatelessWidget {
  const AnimationDemoScreen({super.key});

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('Animated Text Kit Demo')),
      body: Center(
        child: Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: <Widget>[
            // 1. Rotate Animated Text
            Row(
              mainAxisAlignment: MainAxisAlignment.center,
              children: [
                const Text(
                  'Be ',
                  style: TextStyle(fontSize: 30.0, fontWeight: FontWeight.bold),
                ),
                DefaultTextStyle(
                  style: const TextStyle(
                    fontSize: 30.0,
                    color: Colors.blue,
                    fontFamily: 'Horizon', // 폰트가 없을 경우 기본 폰트 사용
                  ),
                  child: AnimatedTextKit(
                    animatedTexts: [
                      RotateAnimatedText('AWESOME'),
                      RotateAnimatedText('OPTIMISTIC'),
                      RotateAnimatedText('DIFFERENT'),
                    ],
                    isRepeatingAnimation: true, // 무한 반복 설정
                    totalRepeatCount: 5, // 총 5회 반복 후 정지
                    pause: const Duration(milliseconds: 1000), // 애니메이션 간 일시 정지 시간
                    displayFullTextOnTap: true,
                    onTap: () {
                      print("Rotate Text Tapped");
                    },
                  ),
                ),
              ],
            ),
            const SizedBox(height: 50),

            // 2. Fade Animated Text
            SizedBox(
              width: 250.0,
              child: DefaultTextStyle(
                style: const TextStyle(
                  fontSize: 28.0,
                  fontWeight: FontWeight.w900,
                  color: Colors.deepPurple,
                ),
                child: AnimatedTextKit(
                  animatedTexts: [
                    FadeAnimatedText('Flutter is Fast'),
                    FadeAnimatedText('Flutter is Beautiful'),
                    FadeAnimatedText('Flutter is Productive'),
                  ],
                  isRepeatingAnimation: false, // 한 번만 실행
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }
}

