import 'package:animated_text_kit/animated_text_kit.dart';
import 'package:flutter/material.dart';

class ControllerExample extends StatefulWidget {
  const ControllerExample({super.key});

  @override
  State<ControllerExample> createState() => _ControllerExampleState();
}

class _ControllerExampleState extends State<ControllerExample> {
  // 1. 컨트롤러 선언
  late AnimatedTextController _controller;
  bool _isPaused = false;

  @override
  void initState() {
    super.initState();
    // 2. 컨트롤러 초기화
    _controller = AnimatedTextController();
  }

  @override
  void dispose() {
    // 메모리 누수 방지를 위해 반드시 dispose
    _controller.dispose();
    super.dispose();
  }

  void _togglePlayPause() {
    setState(() {
      if (_isPaused) {
        _controller.play();
      } else {
        _controller.pause();
      }
      _isPaused = !_isPaused;
    });
  }

  void _resetAnimation() {
    _controller.reset();
    setState(() {
      _isPaused = false;
    });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('Controller Demo')),
      body: Center(
        child: DefaultTextStyle(
          style: const TextStyle(fontSize: 40.0, color: Colors.redAccent),
          child: AnimatedTextKit(
            // 3. 컨트롤러 연결
            controller: _controller,
            animatedTexts: [
              ScaleAnimatedText('START'),
              ScaleAnimatedText('PAUSE'),
              ScaleAnimatedText('RESET'),
            ],
            isRepeatingAnimation: false, // 수동 제어 시 반복은 false로 설정하는 경우가 많음
          ),
        ),
      ),
      floatingActionButton: Row(
        mainAxisAlignment: MainAxisAlignment.end,
        children: [
          FloatingActionButton(
            onPressed: _resetAnimation,
            heroTag: 'reset',
            child: const Icon(Icons.replay),
          ),
          const SizedBox(width: 10),
          FloatingActionButton(
            onPressed: _togglePlayPause,
            heroTag: 'playpause',
            child: Icon(_isPaused ? Icons.play_arrow : Icons.pause),
          ),
        ],
      ),
    );
  }
}

